// Test cases
console.log(checkEmail("abc.123@def.ghi.com.uk"));  // Expected: true
console.log(checkEmail("user@example.com"));        // Expected: true
console.log(checkEmail("user@[127.0.0.1]"));       // Expected: true
console.log(checkEmail("user@.com"));               // Expected: false (missing domain)
